import numpy as np
from scipy.optimize import minimize
import sys

def construct_packing():
    """
    Attempts to 'polish' the current SOTA solution using COBYLA.
    """
    N = 26

    def pack_to_z(c, r):
        z = np.zeros(N*3); z[0::3], z[1::3], z[2::3] = c[:,0], c[:,1], r; return z
    def z_to_pack(z):
        c = np.vstack((z[0::3], z[1::3])).T; r = z[2::3]; return c, r
    def objective(z): return -np.sum(z[2::3])
    def constraint_boundary(z):
        c, r = z_to_pack(z)
        return np.concatenate((c[:,0]-r, 1-c[:,0]-r, c[:,1]-r, 1-c[:,1]-r))
    def constraint_nonoverlap(z):
        c, r = z_to_pack(z)
        pdist_sq = np.sum((c[:,None,:] - c[None,:,:])**2, axis=-1)
        r_sum = r[:,None] + r[None,:]
        iu = np.triu_indices(N, k=1)
        # Add a small epsilon to avoid sqrt(0) issues if circles are perfectly touching
        return np.sqrt(pdist_sq[iu] + 1e-12) - r_sum[iu]

    try:
        # Stage 1: Load the current SOTA packing
        sota_centers = np.loadtxt("storage/Aletheia/sota_2_centers.txt")
        sota_radii = np.loadtxt("storage/Aletheia/sota_2_radii.txt")
        z0 = pack_to_z(sota_centers, sota_radii)
    except IOError:
        print("ERROR: Could not load SOTA packing.", file=sys.stderr)
        return np.zeros((N,2)), np.zeros(N)

    # Stage 2: Polish with COBYLA, which handles constraints directly
    constraints = [
        {'type': 'ineq', 'fun': constraint_boundary},
        {'type': 'ineq', 'fun': constraint_nonoverlap}
    ]

    res = minimize(objective, z0, method='COBYLA', 
                   constraints=constraints,
                   options={'maxiter': 2000, 'rhobeg': 0.0001, 'catol': 1e-9}) # Use a small initial step (rhobeg) for fine-grained search

    final_centers, final_radii = z_to_pack(res.x)
    final_score = -res.fun

    print(f"Polishing with COBYLA complete. Final score: {final_score}", file=sys.stdout)

    return final_centers, final_radii * (1.0 - 1e-9)
